### Direct Register Interrogation Sketch

Rather than hiding the protocol behind an abstraction library, let's communicate directly with the DS3231 silicon using raw `<Wire.h>` commands! This gives you true mastery over I2C register pointers:

```cpp
#include <Wire.h>

const byte DS3231_ADDR = 0x68;

// Helper: Convert BCD byte to standard Decimal integer
byte bcdToDec(byte bcd) {
  return ((bcd >> 4) * 10) + (bcd & 0x0F);
}

void setup() {
  Wire.begin();
  Serial.begin(9600);
  Serial.println("--- DS3231 DIRECT REGISTER READER ---");
}

void loop() {
  // 1. Set the DS3231 internal register pointer to 0x00 (Seconds)
  Wire.beginTransmission(DS3231_ADDR);
  Wire.write(0x00);              // Point to Register 0x00
  Wire.endTransmission();

  // 2. Request 7 consecutive bytes (Seconds through Year)
  Wire.requestFrom(DS3231_ADDR, (byte)7);

  if (Wire.available() >= 7) {
    byte sec  = bcdToDec(Wire.read() & 0x7F);
    byte min  = bcdToDec(Wire.read());
    byte hr   = bcdToDec(Wire.read() & 0x3F); // 24-hr mode mask
    byte day  = bcdToDec(Wire.read());        // Day of week
    byte date = bcdToDec(Wire.read());        // Day of month
    byte mon  = bcdToDec(Wire.read() & 0x1F);
    byte yr   = bcdToDec(Wire.read());

    // 3. Print formatted timestamp to Serial Monitor
    Serial.print("DATE: 20");
    if (yr < 10) Serial.print('0');
    Serial.print(yr);
    Serial.print('/');
    if (mon < 10) Serial.print('0');
    Serial.print(mon);
    Serial.print('/');
    if (date < 10) Serial.print('0');
    Serial.print(date);

    Serial.print("  TIME: ");
    if (hr < 10) Serial.print('0');
    Serial.print(hr);
    Serial.print(':');
    if (min < 10) Serial.print('0');
    Serial.print(min);
    Serial.print(':');
    if (sec < 10) Serial.print('0');
    Serial.println(sec);
  }

  delay(1000); // Poll once per second
}
```

### Code Deconstruction:
- `Wire.write(0x00)`: Writes to the DS3231 internal address register pointer. The next read will start from byte `0x00`.
- `Wire.requestFrom(DS3231_ADDR, 7)`: Asks the DS3231 to transmit 7 consecutive bytes. The DS3231 automatically increments its internal pointer after each byte read!
- `(bcd >> 4) * 10 + (bcd & 0x0F)`: Bit shifts the tens nibble right by 4 and adds the masked units nibble, converting BCD into normal integers.

